/// 트라이 배틀 원소 아이콘.
///
/// 물·숲은 PNG를 **코드에 base64로 내장**한다 — 새 에셋 파일은 OTA 패치에
/// 실리지 않을 수 있지만 Dart 코드는 확실히 실리기 때문. (원본은
/// `assets/elements/`에도 있다 — 다음 스토어 빌드부터는 에셋 로드로 전환 가능.)
/// 불은 출시 빌드에 이미 든 `flame.json` 로티를 정지 프레임으로 쓴다.
library;

import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/widgets.dart';
import 'package:lottie/lottie.dart';

import '../domain/tribattle.dart';

final Uint8List _waterPng = base64Decode(_waterB64);
final Uint8List _forestPng = base64Decode(_forestB64);

/// 원소 아이콘 하나. [size] 정사각형.
class ElementIcon extends StatelessWidget {
  const ElementIcon(this.elem, {super.key, required this.size});
  final TriElement elem;
  final double size;

  @override
  Widget build(BuildContext context) {
    switch (elem) {
      case TriElement.water:
        return Image.memory(_waterPng,
            width: size, height: size, gaplessPlayback: true);
      case TriElement.forest:
        return Image.memory(_forestPng,
            width: size, height: size, gaplessPlayback: true);
      case TriElement.fire:
        // 로티 정지 프레임 — 스타일이 플랫 아이콘과 어긋나면 SVG로 교체 예정.
        return SizedBox(
            width: size,
            height: size,
            child: Lottie.asset('assets/lottie/flame.json', animate: false));
    }
  }
}

